async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});let d;try{d=await r.json()}catch{throw new Error('O servidor não respondeu. Recarregue e tente novamente.')}if(!r.ok)throw Object.assign(new Error(d.mensagem||'Não foi possível concluir.'),{status:r.status});return d}
const btn=(label,action,attrs='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`,link=(label,href,cls='btn')=>`<a class="${cls}" href="${href}">${label}</a>`;
