function header(){return `<a class="skip" href="#conteudo">Pular para o conteúdo</a><div class="topbar"><div class="wrap"><span>${icon('caminhao')} Sem preço fixo. Sua oferta, seu achado.</span><span>Pequenas marcas. Grandes histórias.</span><span>${icon('brilho')} A loja decide qual oferta aceitar</span></div></div><header class="header"><div class="wrap header-main"><a class="brand" href="/index.html" aria-label="Âmbar — início"><img src="/assets/marca/logo-ambar.svg" alt="Âmbar"></a><form class="searchbox" data-form="search">${icon('busca')}<input name="q" aria-label="O que você está procurando?" placeholder="Encontre seu próximo achado" value="${e(new URLSearchParams(location.search).get('q')||'')}"><button aria-label="Buscar">${icon('seta-direita')}</button></form><div class="header-actions"><span class="demo-chip">DEMONSTRAÇÃO</span><a class="account-link" href="${S.me?homeFor(S.me):'/login.html'}">${icon('usuario')}<span><small>${S.me?'Olá, '+e(S.me.nome.split(' ')[0]):'Boas-vindas'}</small>${S.me?'Minha conta':'Entre ou cadastre-se'}</span></a><a class="icon-btn" href="/conta.html#favoritos" aria-label="Favoritos">${icon('coracao')}</a><a class="icon-btn bag" href="/conta.html#ofertas" aria-label="Minhas ofertas">${icon('tag')}</a></div></div><nav class="navbar" aria-label="Navegação principal"><div class="wrap nav-inner"><a href="/busca.html">${icon('menu')} Todas as categorias</a><a class="nav-hot" href="/busca.html?com_ofertas=1">Achados em disputa</a><a href="/busca.html?ordem=novidades">Novidades</a><a href="/busca.html?categoria=casa-e-decoracao">Casa & decoração</a><a href="/busca.html?categoria=moda">Seu estilo</a><a href="/index.html#lojas">Lojas independentes</a><a href="/vender.html">Venda na Âmbar ${icon('seta-direita')}</a></div></nav></header>`}
function footer(){return `<footer class="foot"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="/index.html"><img src="/assets/marca/logo-ambar.svg" alt="Âmbar"></a><p>Achados que brilham.<br>Uma vitrine para quem cria com propósito e para quem escolhe com carinho.</p></div><div><h4>Encontre seu achado</h4><a href="/busca.html">Todos os produtos</a><a href="/busca.html?com_ofertas=1">Achados em disputa</a><a href="/index.html#lojas">Conheça as lojas</a></div><div><h4>Vamos conversar</h4><a href="/sobre.html">Sobre a Âmbar</a><a href="/vender.html">Quero vender</a><a href="/sobre.html#demonstracao">Sobre esta demonstração</a></div><div><h4>Seu espaço</h4><a href="/conta.html">Minha conta</a><a href="/conta.html#pedidos">Acompanhar pedidos</a><a href="/login.html">Testar os três perfis</a><button class="icon-btn" data-action="sound" aria-label="${S.sound?'Desativar':'Ativar'} sons">${icon(S.sound?'som':'som-mudo')}</button></div></div><div class="footer-bottom"><span>© 2026 Âmbar. Feito para descobrir.</span><span>Demonstração acadêmica · Sem cobranças reais.</span><span>Ofertas · Negociação direta</span></div></div></footer>`}
function card(p,n=0){const open=p.negociacao_status==='aberto'&&p.estoque>0;return `<article class="product" style="--n:${n%8}"><div class="product-photo"><a href="/produto.html?id=${p.id}"><img src="${e(p.imagem)}" alt="${e(p.nome)}" loading="lazy"></a><span class="tag ${open?'':'sale'}">${open?'SEM PREÇO FIXO':'OFERTA ACEITA'}</span><button class="favorite ${S.favs.has(p.id)?'active':''}" data-action="favorite" data-id="${p.id}" aria-label="Favoritar ${e(p.nome)}" aria-pressed="${S.favs.has(p.id)}">${icon('coracao')}</button><a class="quick-add" href="/produto.html?id=${p.id}" aria-label="Fazer oferta em ${e(p.nome)}">${icon('seta-direita')}</a></div><div class="product-info"><a class="shop-label" href="/loja.html?slug=${e(p.loja?.slug)}">${e(p.loja?.nome||'Âmbar')}</a><a class="product-name" href="/produto.html?id=${p.id}">${e(p.nome)}</a><div class="offer-caption">${p.maior_oferta?'Maior oferta até agora':'O primeiro lance pode ser seu'}</div><div class="price">${p.maior_oferta?money(p.maior_oferta):'Você faz o preço.'}</div><div class="pix">${p.total_ofertas} ${p.total_ofertas===1?'oferta':'ofertas'} · ${open?'Negociação aberta':'Negociação encerrada'}</div>${p.minha_oferta?`<div class="my-offer">Sua oferta: ${money(p.minha_oferta)}</div>`:''}</div></article>`}
