async function home(){products=(await api('produtos?limite=100')).itens;const cats=[['Casa & decoração','casa-e-decoracao','casa'],['Cozinha & café','cozinha-e-cafe','cafe'],['Moda','moda','camiseta'],['Bolsas & couro','bolsas-e-couro','bolsa'],['Joias & relógios','joias-e-relogios','joia'],['Eletrônicos','eletronicos','fone'],['Beleza','beleza','beleza'],['Ver todas','','menu']];return `<section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('brilho')} UM ENCONTRO COM O EXTRAORDINÁRIO</div><h1>Achados especiais.<br>O preço? <em>Você propõe.</em></h1><p>Aqui, cada achado começa com a sua oferta.<br>Descubra, faça seu lance e negocie direto com a loja.</p>${link('Encontre seu próximo achado '+icon('seta-direita'),'/busca.html')}<div class="hero-foot">${icon('loja')} ${S.shops.length} lojas independentes. Um mundo de descobertas.</div></div><div class="hero-photo"><img src="${img('1600210492486-724fe5c67fb0')}" alt="Sala acolhedora com plantas, madeira e luz natural" fetchpriority="high"><div class="hero-stamp">PEQUENAS MARCAS${icon('brilho')}grandes achados</div><a class="hero-note" href="/busca.html?categoria=casa-e-decoracao"><span><small>COLEÇÃO CASA & AFETO</small>A sua casa, do seu jeito.</span>${icon('seta-direita')}</a></div></section><div class="trust"><div class="wrap"><span>${icon('escudo')} Você escolhe a sua oferta</span><span>${icon('verificado')} Apoie marcas independentes</span><span>${icon('caminhao')} Sem preço de etiqueta</span><span>${icon('brilho')} A loja avalia cada proposta</span></div></div><div class="wrap"><section class="section reveal"><div class="section-head"><h2>Por onde vamos começar?</h2>${link('Todas as categorias '+icon('seta-direita'),'/busca.html','text-link')}</div><div class="categories">${cats.map(([n,s,i])=>`<a class="category" href="/busca.html${s?'?categoria='+s:''}"><span class="category-art">${icon(i)}</span>${n}</a>`).join('')}</div></section><section class="section"><div class="section-head with-pills"><div><span class="eyebrow" style="color:#ac6846">ACHADOS SEM PREÇO FIXO</span><h2 style="margin-top:9px">Você encontra. Você faz sua oferta.</h2></div><div class="pills"><button class="pill active" data-action="homefilter" data-value="">Nossa seleção</button><button class="pill" data-action="homefilter" data-value="oferta">Em disputa</button><button class="pill" data-action="homefilter" data-value="novo">Novidades</button></div></div><div class="products" id="home-products">${selected(products).map(card).join('')}</div><div style="text-align:center;margin-top:20px">${link('Mais achados esperam por você '+icon('seta-direita'),'/busca.html','btn light')}</div></section><div class="editorial reveal"><a class="editorial-card" href="/busca.html?categoria=casa-e-decoracao"><img src="${img('1605702098590-d552a98dc93d')}" alt="Poltrona de madeira" loading="lazy"><div class="editorial-copy"><span class="eyebrow">CASA COM PERSONALIDADE</span><h2>Seu cantinho.<br>Seu jeito de morar.</h2><span class="text-link">Encontre inspiração ${icon('seta-direita')}</span></div></a><a class="editorial-card" href="/busca.html?categoria=cozinha-e-cafe"><img src="${img('1553329701-1abe5e1bf403')}" alt="Café para desacelerar" loading="lazy"><div class="editorial-copy"><span class="eyebrow">PAUSAS QUE FAZEM BEM</span><h2>O extraordinário<br>mora nos rituais.</h2><span class="text-link">Explore cozinha & café ${icon('seta-direita')}</span></div></a></div><section class="section reveal" id="lojas"><div class="section-head"><div><h2>Por trás de cada achado, uma história.</h2><p>Conheça as pequenas marcas que fazem parte da Âmbar.</p></div></div><div class="shops">${[S.shops[0],S.shops[6],S.shops[4],S.shops[3]].map(shop).join('')}</div><details style="margin-top:20px"><summary class="text-link" style="cursor:pointer">Conheça todas as ${S.shops.length} lojas</summary><div class="shops" style="margin-top:20px">${S.shops.filter((_,i)=>![0,6,4,3].includes(i)).map(shop).join('')}</div></details></section><section class="story reveal"><img src="${img('1441986300917-64674bd600d8')}" alt="Loja independente" loading="lazy"><div class="story-copy"><span class="eyebrow">SUA MARCA, NOSSA VITRINE</span><h2>Você cria com amor.<br>A gente ajuda a brilhar.</h2><p>Seu trabalho merece ser descoberto. Traga sua loja para a Âmbar e encontre quem valoriza o que você faz.</p>${link('Quero fazer parte '+icon('seta-direita'),'/vender.html','btn light')}</div></section>${newsletter()}</div>`}
async function catalog(isShop=false){const q=new URLSearchParams(location.search);let store;if(isShop){store=(await api('lojas/'+encodeURIComponent(q.get('slug')))).loja;q.set('loja',store.slug)}const d=await api('produtos?'+q);products=d.itens;const cat=S.cats.find(c=>c.slug===q.get('categoria')),h=store?.nome||cat?.nome||(q.get('q')?'Resultados para “'+q.get('q')+'”':q.get('com_ofertas')?'Achados em disputa':'O próximo lance é seu.');return `<div class="wrap">${crumb(isShop?'Lojas independentes':'Explore')}${title(e(h),e(store?.descricao||'Sem etiqueta de preço. Descubra um achado e diga quanto ele vale para você.'))}<button class="btn light sm mobile-only" style="margin-bottom:20px" data-action="filters">${icon('ajustes')} Filtrar achados</button><div class="catalog"><aside class="filters"><div class="filter-group"><h3>Categorias</h3><a class="filter-link" href="/busca.html">Todas as categorias</a>${S.cats.map(c=>`<a class="filter-link ${cat?.slug===c.slug?'active':''}" href="/busca.html?categoria=${c.slug}">${e(c.nome)} ${icon('chevron-direita')}</a>`).join('')}</div><div class="filter-group"><h3>Encontre sua oportunidade</h3><a class="filter-link" href="/busca.html?abertos=1">Aceitando ofertas ${icon('check')}</a><a class="filter-link" href="/busca.html?sem_ofertas=1&abertos=1">Seja o primeiro ${icon('brilho')}</a><a class="filter-link" href="/busca.html?com_ofertas=1">Com ofertas ${icon('usuarios')}</a></div><a class="text-link" href="/busca.html">Limpar filtros</a><div class="notice" style="margin-top:25px">Sem preço inicial definido. A loja avalia e aceita a proposta.</div></aside><div><div class="results"><span>${d.total} achados encontrados</span><select aria-label="Ordenar produtos" id="sort"><option value="relevancia">Nossa seleção</option><option value="mais_ofertas">Mais disputados</option><option value="maior_oferta">Maiores ofertas</option><option value="novidades">Mais recentes</option></select></div><div class="products">${d.itens.length?d.itens.map(card).join(''):empty('Nenhum achado por aqui.','Tente outra busca ou remova os filtros.')}</div>${d.paginas>1?`<nav class="pagination" aria-label="Paginação">${Array.from({length:d.paginas},(_,i)=>`<button class="pill ${d.pagina===i+1?'active':''}" data-action="page" data-value="${i+1}">${i+1}</button>`).join('')}</nav>`:''}</div></div>${newsletter()}</div>`}
function desc(p){return `<p>${e(p.descricao)}</p><div class="checks"><div>${icon('loja')} Vendido por ${e(p.loja.nome)}, de ${e(p.loja.cidade)}.</div><div>${icon('pacote')} Estoque acompanhado pela loja.</div><div>${icon('info')} Fotos ilustrativas do catálogo de demonstração.</div></div>`}
async function detail(){const id=new URLSearchParams(location.search).get('id'),p=(await api('produtos/'+id)).produto;detailProduct=p;products=[p];const [a,b,c,d]=await Promise.all([api('produtos/'+id+'/avaliacoes'),api('produtos/'+id+'/perguntas'),api('produtos?categoria='+p.categoria.slug+'&limite=5'),api('produtos/'+id+'/lances')]);p.reviews=a.itens;p.questions=b.itens;p.bids=d;const open=d.leilao.status==='aberto'&&p.estoque>0;return `<div class="wrap">${crumb(p.nome)}<div class="detail"><img class="detail-img" src="${e(p.imagem)}" alt="${e(p.nome)}"><div class="detail-copy"><a class="shop-label" href="/loja.html?slug=${p.loja.slug}">${e(p.loja.nome)} · ${e(p.loja.cidade)}, ${p.loja.uf}</a><h1>${e(p.nome)}</h1><p>${e(p.descricao)}</p><div class="offer-summary"><span class="eyebrow">${open?'VOCÊ ESCOLHE QUANTO QUER PAGAR':'ESTA RODADA FOI ENCERRADA'}</span><div class="offer-caption" style="margin-top:16px">Maior oferta recebida</div><div class="offer-amount" id="highest-offer">${p.maior_oferta?money(p.maior_oferta):'Seja o primeiro.'}</div><div class="row between small muted"><span id="offer-count">${d.leilao.total_ofertas} ${d.leilao.total_ofertas===1?'oferta':'ofertas'} nesta rodada</span><span>${badge(open?'aberta':'encerrada')}</span></div></div>${open?(S.me?.nivel==='comprador'?`<form data-form="offer" class="offer-form"><label for="offer-value">Qual é a sua oferta por 1 unidade?</label><div class="row"><div class="currency-input"><span>R$</span><input id="offer-value" name="valor" aria-label="Valor da sua oferta" type="number" min="0.01" max="1000000" step="0.01" placeholder="Você decide" required></div><button class="btn">Enviar oferta ${icon('seta-direita')}</button></div><label class="checkline"><input type="checkbox" required> Entendo que a loja precisa aceitar minha oferta.</label><p class="error" id="offer-error" role="alert"></p></form>`:S.me?`<div class="notice">${icon('info')} Para fazer ofertas, entre com o perfil comprador.</div>${link('Trocar para comprador','/login.html','btn light full')}`:link('Entre para fazer sua oferta '+icon('seta-direita'),'/login.html?voltar='+encodeURIComponent('/produto.html?id='+p.id),'btn full')):`<div class="notice">${icon('check')} A loja já aceitou uma oferta nesta rodada. Acompanhe suas propostas na sua conta.</div>${link('Ver minhas ofertas','/conta.html#ofertas','btn light full')}`}<p class="small muted" style="margin:15px 0 20px">Sem preço fixo e sem encerramento automático. A loja escolhe a oferta que aceita. Uma unidade por negociação; entrega a combinar. Nenhuma cobrança real nesta demonstração.</p><button class="text-link" data-action="favorite" data-id="${p.id}">${icon('coracao')} Guardar nos favoritos</button></div></div><section class="bids-section"><div class="section-head"><div><h2>A conversa começa com uma oferta.</h2><p>As ofertas se atualizam automaticamente. Você pode melhorar seu próprio lance.</p></div>${btn('Atualizar '+icon('historico'),'refresh-offers','','light sm')}</div><div id="bid-list">${bidsHTML(d,p)}</div></section><div class="tabs"><button class="active" data-action="tab" data-value="descricao">Sobre este achado</button><button data-action="tab" data-value="reviews">Avaliações do catálogo (${p.reviews.length})</button><button data-action="tab" data-value="questions">Perguntas (${p.questions.length})</button></div><div id="product-tab" class="tab-content">${desc(p)}</div><section class="section"><div class="section-head"><h2>Mais achados esperando sua oferta.</h2></div><div class="products">${c.itens.filter(v=>v.id!==p.id).slice(0,4).map(card).join('')}</div></section></div>`}
function bidsHTML(d,p){if(!d.lances.length)return `<div class="bid-empty">${icon('brilho')} Ainda sem ofertas. Quanto este achado vale para você?</div>`;return `<div class="bid-list">${d.lances.map((b,i)=>`<div class="bid-row ${b.minha?'mine':''}"><span class="bid-place">${i===0?icon('brilho'):String(i+1).padStart(2,'0')}</span><div><strong>${e(b.participante)} ${b.minha?'<span class="demo-chip">VOCÊ</span>':''}</strong><small>${new Date(b.criado_em).toLocaleString('pt-BR')}</small></div><div class="bid-money"><strong>${money(b.valor)}</strong>${badge(b.status)}</div>${d.gerenciar&&b.status==='aberta'&&d.leilao.status==='aberto'?btn('Aceitar oferta','accept-offer',`data-id="${e(b.id)}" data-value="${b.valor}"`,'sm'):''}</div>`).join('')}</div>`}
async function refreshBids(){if(!detailProduct||!location.pathname.endsWith('produto.html'))return;const d=await api('produtos/'+detailProduct.id+'/lances');detailProduct.bids=d;if($('#bid-list'))$('#bid-list').innerHTML=bidsHTML(d,detailProduct);if($('#highest-offer'))$('#highest-offer').textContent=d.leilao.maior_oferta?money(d.leilao.maior_oferta):'Seja o primeiro.';if($('#offer-count'))$('#offer-count').textContent=d.leilao.total_ofertas+(d.leilao.total_ofertas===1?' oferta':' ofertas')+' nesta rodada';const f=$('[data-form="offer"]');if(f&&d.leilao.status!=='aberto'){f.innerHTML='<div class="notice">Esta negociação foi encerrada pela loja.</div>'}}
function auth(register=false){return `<div class="auth"><aside class="auth-art"><img src="${img('1600210492486-724fe5c67fb0')}" alt="Casa cheia de vida"><div><span class="eyebrow">BEM-VINDO AO SEU NOVO CANTINHO</span><h2 style="margin-top:17px">Bons encontros.<br>Belos achados.</h2><p>O próximo objeto da sua história pode estar aqui.</p></div></aside><div class="auth-form"><span class="eyebrow">VAMOS NOS CONHECER</span><h1>${register?'Crie sua conta.':'Que bom ter você aqui.'}</h1><p>${register?'Guarde favoritos e descubra peças com a sua cara.':'Entre para continuar suas descobertas.'}</p><form data-form="${register?'register':'login'}">${register?field('Seu nome','nome','text','','required minlength="3" autocomplete="name"'):''}${field('E-mail','email','email','','required autocomplete="email"')}${field('Senha','senha','password','','required minlength="8" autocomplete="'+(register?'new-password':'current-password')+'"')}<p class="error" id="auth-error" role="alert"></p><button class="btn full">${register?'Criar minha conta':'Entrar na minha conta'} ${icon('seta-direita')}</button></form><p class="small" style="text-align:center;margin-top:20px">${register?'Já tem conta? '+link('Entrar','/login.html','text-link'):'Primeira visita? '+link('Criar conta','/cadastro.html','text-link')}</p><div class="demo-accounts"><strong class="small">Explore a demonstração</strong><p>Escolha um perfil. Todos usam a senha <strong>Ambar@2026</strong>.</p><div class="row">${['comprador','vendedor','admin'].map(r=>btn(r==='admin'?'Administrador':r[0].toUpperCase()+r.slice(1),'demo-login',`data-value="${r}"`,'light')).join('')}</div><p style="margin:10px 0 0">Dados fictícios. Nenhuma compra gera cobrança.</p></div></div></div>`}
function needLogin(){setTimeout(()=>go('/login.html?voltar='+encodeURIComponent(location.pathname+location.search+location.hash)),0);return '<div class="loading"><span class="spinner"></span></div>'}
function localPhoto(s){const m=String(s||'').match(/photo-[\w-]+/);return String(s||'').startsWith('https://images.unsplash.com')&&m?'/assets/fotos/'+m[0]+'.jpg':s||'/assets/fotos/produto.svg'}
async function cart(){if(!S.cart.length)return `<div class="wrap">${crumb('Sua sacola')}${title('Um espaço para seus achados.')}${empty('Sua sacola está esperando.','Tem muita coisa especial para descobrir por aqui.')}</div>`;products=(await api('produtos?ids='+S.cart.map(i=>i.produto_id).join(',')+'&limite=100')).itens;const total=S.cart.reduce((s,i)=>s+(products.find(p=>p.id===i.produto_id)?.preco||0)*i.quantidade,0);return `<div class="wrap">${crumb('Sua sacola')}${title('Seus próximos achados.',count()+' itens com um lugar reservado na sua história.')}<div class="cart-layout"><div>${S.cart.map(i=>{const p=products.find(p=>p.id===i.produto_id);return `<article class="cart-item"><img src="${e(p?.imagem||i.imagem)}" alt="${e(i.nome)}"><div><span class="shop-label">${e(p?.loja?.nome||'Indisponível')}</span><h3><a href="/produto.html?id=${i.produto_id}">${e(p?.nome||i.nome)}</a></h3><div class="quantity"><button data-action="cartqty" data-id="${i.produto_id}" data-value="-1" aria-label="Diminuir ${e(i.nome)}">−</button><span>${i.quantidade}</span><button data-action="cartqty" data-id="${i.produto_id}" data-value="1" aria-label="Aumentar ${e(i.nome)}">+</button></div>${!p||i.quantidade>p.estoque?'<p class="error">Quantidade indisponível. Ajuste ou remova este item.</p>':''}</div><div style="text-align:right"><div class="price">${money((p?.preco||0)*i.quantidade)}</div><button class="icon-btn" data-action="remove" data-id="${i.produto_id}" aria-label="Remover ${e(i.nome)}">${icon('lixeira')}</button></div></article>`}).join('')}<div style="margin-top:25px">${link('Continuar descobrindo','/busca.html','text-link')}</div></div><aside class="summary"><h2>Resumo da sacola</h2><div class="summary-line"><span>Produtos (${count()})</span><span>${money(total)}</span></div><div class="summary-line"><span>Frete</span><span>${total>=199?'Grátis':'No checkout'}</span></div><div class="summary-line"><span>Desconto no Pix</span><span>5% no checkout</span></div><div class="summary-line summary-total"><span>Subtotal</span><span>${money(total)}</span></div>${link('Continuar para entrega '+icon('seta-direita'),'/checkout.html','btn full')}<p class="small" style="text-align:center;margin-top:15px">Compra de demonstração, sem cobrança.</p></aside></div></div>`}
function addressFields(a={}){return `<div class="fields">${[['Quem vai receber?','destinatario'],['CEP','cep'],['Rua ou avenida','logradouro'],['Número','numero'],['Bairro','bairro'],['Complemento (opcional)','complemento'],['Cidade','cidade'],['Estado (UF)','uf']].map(([l,n])=>field(l,n,'text',a[n]||'',(n==='complemento'?'':'required ')+(n==='cep'?'maxlength="9" inputmode="numeric"':n==='uf'?'minlength="2" maxlength="2"':''))).join('')}</div>`}
function quoteHTML(q){return `<div class="summary-line"><span>Produtos</span><span>${money(q.subtotal)}</span></div><div class="summary-line"><span>Entrega</span><span>A combinar com a loja</span></div>${q.desconto_cupom?`<div class="summary-line"><span>Cupom ${e(q.cupom)}</span><span>−${money(q.desconto_cupom)}</span></div>`:''}${q.desconto_pix?`<div class="summary-line"><span>Desconto Pix</span><span>−${money(q.desconto_pix)}</span></div>`:''}<div class="summary-line summary-total"><span>Total</span><span>${money(q.total)}</span></div>`}
async function checkout(){if(!S.me)return needLogin();if(!S.cart.length)return `<div class="wrap">${crumb('Checkout')}${empty('Sua sacola está vazia.','Escolha um achado para começar.')}</div>`;if(S.me.nivel==='vendedor')return `<div class="wrap">${crumb('Checkout')}${empty('Entre como comprador.','Use o perfil comprador para testar uma compra.','Trocar de perfil','/login.html')}</div>`;orderKey=uid();const addresses=(await api('enderecos')).enderecos;quote=await api('pedidos/simular','POST',{itens:S.cart,forma_pagamento:'pix'});return `<div class="wrap">${crumb('Finalizar compra')}${title('Quase seus.')}<div class="notice">${icon('info')} Ambiente de demonstração. Use dados fictícios. Não pedimos número de cartão e não geramos cobranças Pix.</div><form data-form="checkout" id="checkout"><div class="cart-layout"><div><section class="form-card"><div class="row between" style="margin-bottom:20px"><h2 style="margin:0">01. Onde entregar?</h2>${btn('Usar endereço de exemplo','example-address','type="button"','light sm')}</div>${addresses.length?`<div class="field"><label for="addresses">Endereços salvos</label><select id="addresses"><option value="">Preencher outro endereço</option>${addresses.map((a,i)=>`<option value="${i}">${e(a.logradouro)}, ${e(a.numero)} · ${e(a.cidade)}</option>`).join('')}</select></div>`:''}${addressFields()}</section><section class="form-card"><h2>02. Como prefere pagar?</h2><div class="payment-options"><button class="payment active" type="button" data-action="payment" data-value="pix">${icon('pix')} Pix<small>5% de desconto</small></button><button class="payment" type="button" data-action="payment" data-value="cartao">${icon('cartao')} Cartão<small>Até 10x sem juros</small></button></div><input type="hidden" name="forma_pagamento" value="pix"><div id="installments" hidden><label for="installment-choice">Parcelamento de demonstração</label><select id="installment-choice" name="parcelas">${Array.from({length:Math.min(10,Math.max(1,Math.floor(quote.total/20)))},(_,i)=>`<option value="${i+1}">${i+1}x sem juros</option>`).join('')}</select></div><p class="small">Você confirma o pagamento na próxima tela, apenas para testar o fluxo.</p></section></div><aside class="summary"><h2>Seus achados</h2>${S.cart.map(i=>`<div class="summary-line"><span>${i.quantidade}× ${e(i.nome)}</span></div>`).join('')}<div class="coupon"><input name="cupom" aria-label="Cupom de desconto" placeholder="Tem um cupom?"><button class="btn light sm" type="button" data-action="coupon">Aplicar</button></div><div id="quote">${quoteHTML(quote)}</div><p class="error" id="checkout-error"></p><button type="submit" class="btn full">Criar pedido de teste ${icon('seta-direita')}</button><p class="small" style="text-align:center;margin-top:13px">Nenhum valor será cobrado.</p></aside></div></form><script type="application/json" id="saved-addresses">${JSON.stringify(addresses).replace(/</g,'\\u003c')}</script></div>`}
async function order(){if(!S.me)return needLogin();const p=(await api('pedidos/'+new URLSearchParams(location.search).get('id'))).pedido;orders=[p];const stages=['aguardando_pagamento','pago','preparando','enviado','entregue'];return `<div class="wrap">${crumb('Seu pedido')}<div class="order-hero">${icon(p.status==='cancelado'?'fechar':p.status==='aguardando_pagamento'?'relogio':'check')}<h1>${p.status==='aguardando_pagamento'?'Seu achado está reservado.':p.status==='cancelado'?'Pedido cancelado.':'Sua história está a caminho.'}</h1><p class="small">${e(p.codigo)} · ${date(p.criado_em)} · ${money(p.total)}</p><div style="margin-top:15px">${badge(p.status)}</div></div>${p.status!=='cancelado'?`<div class="timeline">${stages.map((s,i)=>`<div class="step ${i<=stages.indexOf(p.status)?'done':''}"><strong>0${i+1}</strong>${names[s]}</div>`).join('')}</div>`:''}<div class="notice">${icon('info')} Pedido de demonstração. Não haverá cobrança ou envio físico.</div><div class="cart-layout"><div class="form-card"><h2>Seus achados</h2>${orderItems(p)}${p.endereco?`<h3 style="margin-top:25px">Endereço de entrega</h3><p class="small" style="margin-top:10px">${e(p.endereco.destinatario)}<br>${e(p.endereco.logradouro)}, ${e(p.endereco.numero)}<br>${e(p.endereco.cidade)} — ${e(p.endereco.uf)}</p>`:''}</div><aside class="summary"><h2>Resumo do pedido</h2>${quoteHTML(p)}${p.status==='aguardando_pagamento'&&p.comprador_id===S.me.id?btn('Simular pagamento aprovado','pay',`data-id="${e(p.id)}"`,'full'):''}${['aguardando_pagamento','pago'].includes(p.status)&&p.comprador_id===S.me.id?btn('Cancelar pedido','cancel',`data-id="${e(p.id)}"`,'light full'):''}<div style="margin-top:20px">${link('Ver meus pedidos','/conta.html#pedidos','text-link')}</div></aside></div></div>`}
function orderItems(p){return p.itens.map(i=>`<div class="cart-item"><img src="${e(localPhoto(i.produto_imagem))}" alt="${e(i.produto_nome)}"><div><h3>${e(i.produto_nome)}</h3><p class="small">${i.quantidade} unidade(s)</p></div><strong class="small">${money(i.subtotal)}</strong></div>`).join('')}
async function account(){if(!S.me)return needLogin();const tab=location.hash.slice(1)||'ofertas';let content;if(tab==='ofertas'){content=await myOffers()}else if(tab==='pedidos'){const ps=(await api('pedidos/meus')).pedidos;content=ps.length?ps.map(p=>`<article class="order-box"><div class="row between"><h3>${e(p.codigo)}</h3>${badge(p.status)}</div><p>${date(p.criado_em)} · ${p.itens.reduce((a,i)=>a+i.quantidade,0)} itens · ${money(p.total)}</p><div class="row between"><div class="order-thumbs">${p.itens.slice(0,4).map(i=>`<img src="${e(localPhoto(i.produto_imagem))}" alt="${e(i.produto_nome)}">`).join('')}</div>${link('Ver pedido '+icon('seta-direita'),'/pedido.html?id='+p.id,'btn light sm')}</div></article>`).join(''):empty('Sua história começa aqui.','Seus pedidos vão aparecer neste espaço.')}else if(tab==='favoritos'){products=(await api('favoritos')).itens;content=`<div class="products account-products">${products.length?products.map(card).join(''):empty('Guarde o que faz seu coração brilhar.','Toque no coração dos produtos para guardar seus favoritos.')}</div>`}else if(tab==='enderecos'){const as=(await api('enderecos')).enderecos;content=`<div class="row between" style="margin-bottom:20px"><p class="small">Endereços para suas próximas entregas.</p>${btn('Novo endereço '+icon('mais'),'new-address','','sm')}</div>${as.length?as.map(a=>`<div class="address-card"><div><strong>${e(a.destinatario)}</strong>${e(a.logradouro)}, ${e(a.numero)}<br>${e(a.cidade)} — ${e(a.uf)} · ${e(a.cep)}</div><button class="icon-btn" data-action="delete-address" data-id="${e(a.id)}" aria-label="Remover endereço">${icon('lixeira')}</button></div>`).join(''):empty('Nenhum endereço salvo.','Adicione um endereço para agilizar sua compra.','')}`}else content=`<form class="form-card" data-form="profile"><h2>Seus dados</h2>${field('Nome','nome','text',S.me.nome,'required')}${field('E-mail','email','email',S.me.email,'disabled')}<button class="btn">Salvar alterações</button></form><form class="form-card" data-form="password"><h2>Alterar senha</h2>${field('Senha atual','senha_atual','password','','required')}${field('Nova senha','nova_senha','password','','required minlength="8"')}<button class="btn light">Atualizar senha</button></form>${btn('Sair de todos os dispositivos','logout-all','','light')}`;return `<div class="wrap">${crumb('Minha conta')}${title('Seu cantinho na Âmbar.','Olá, '+e(S.me.nome.split(' ')[0])+'. É bom ter você por aqui.')}<div class="account-layout"><nav class="account-menu">${[['ofertas','Minhas ofertas','tag'],['pedidos','Ofertas aceitas','pacote'],['favoritos','Favoritos','coracao'],['enderecos','Endereços','pin'],['perfil','Meus dados','usuario']].map(([t,l,i])=>`<a class="${tab===t?'active':''}" href="/conta.html#${t}">${icon(i)} ${l}</a>`).join('')}<a href="/index.html" data-action="logout">${icon('sair')} Sair</a></nav><section>${content}</section></div></div>`}
async function about(){return `<div class="wrap">${crumb('Nossa história')}<article class="about"><span class="eyebrow">PRAZER, SOMOS A ÂMBAR</span><h1 style="margin-top:15px">O valor está nos detalhes.<br>E nas pessoas.</h1><img src="${img('1441986300917-64674bd600d8')}" alt="Uma loja cheia de histórias"><p>A Âmbar é um encontro entre quem cria e quem encontra. Uma vitrine de lojas independentes, produtos escolhidos com cuidado e histórias que merecem ser conhecidas.</p><p>Da primeira xícara de café ao último detalhe da decoração: objetos fazem parte de uma vida com mais personalidade.</p><h2 id="demonstracao">Uma loja para explorar e testar.</h2><p>Este projeto acadêmico usa um catálogo e contas fictícias. As ofertas que você faz ficam gravadas nesta demonstração. Compradores enviam ofertas sem preço fixo; a loja decide qual aceitar. A aceitação reserva uma unidade e cria uma negociação. Os pagamentos são simulados, sem cobrança, emissão fiscal ou entrega. Use dados fictícios durante os testes.</p><p>Cadastros, favoritos, produtos e pedidos ficam gravados nas tabelas MySQL da aplicação. A sacola e a preferência de som ficam neste navegador. Esta versão grava os dados diretamente no MySQL da aplicação.</p><h2>Créditos que merecem brilhar.</h2><p>Fotos: Unsplash, ilustrativas e salvas no projeto. Fontes: Instrument Sans e Fraunces, com licenças OFL incluídas. Identidade Âmbar e vídeo: projeto original. Efeitos de som: sintetizados no navegador, opcionais.</p><p>Os áudios do ElevenLabs não vieram no zip e não fazem parte desta publicação. Resposta a perguntas, novas avaliações e administração de banners, categorias e configurações permanecem no backend MySQL, sem integração completa nesta interface.</p><div class="row wrap-mobile">${link('Explorar os achados','/busca.html')}${link('Testar os perfis','/login.html','btn light')}</div></article></div>`}
async function sell(){return `<div class="wrap">${crumb('Venda na Âmbar')}<div class="detail"><div class="detail-copy"><span class="eyebrow">PARA QUEM CRIA COM PROPÓSITO</span><h1>Seu trabalho merece<br>ser descoberto.</h1><p>Uma loja só sua, em uma vitrine cheia de possibilidades. Reúna produtos, organize pedidos e acompanhe cada nova venda.</p><div class="checks"><div>${icon('check')} Cadastre e edite seus produtos.</div><div>${icon('check')} Acompanhe estoque e pedidos em um só lugar.</div><div>${icon('check')} Conte a história da sua marca.</div></div>${link('Conhecer o painel de demonstração','/login.html','btn light')}</div><section class="form-card"><h2>Vamos fazer parte da sua história?</h2><p class="small" style="margin-bottom:25px">A solicitação fica visível ao administrador da demonstração.</p>${S.me?`<form data-form="sell">${field('Nome da loja','nome_loja','text','','required minlength="3"')}<div class="field"><label for="story">Conte sobre sua marca</label><textarea id="story" name="descricao" minlength="10" required></textarea></div><div class="fields">${field('Cidade','cidade','text','','required')}${field('Estado (UF)','uf','text','','required minlength="2" maxlength="2"')}</div><button class="btn full" style="margin-top:20px">Enviar meu interesse ${icon('seta-direita')}</button></form>`:link('Entre para apresentar sua marca','/login.html?voltar=%2Fvender.html','btn full')}</section></div></div>`}
function productsTable(ps){return ps.length?`<div class="table-scroll"><table><thead><tr><th>Produto</th><th>Maior oferta</th><th>Estoque</th><th>Status</th><th>Ações</th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="product-cell"><img src="${e(p.imagem)}" alt=""><span><a href="/produto.html?id=${p.id}">${e(p.nome)}</a><small>${e(p.categoria?.nome)} · #${p.id}</small></span></div></td><td>${p.maior_oferta?money(p.maior_oferta):'Sem ofertas'}<small>${p.total_ofertas} ${p.total_ofertas===1?'oferta':'ofertas'}</small></td><td ${p.estoque<=5?'style="color:#ad643e"':''}>${p.estoque} un.</td><td>${badge(!p.ativo?'inativo':p.negociacao_status==='encerrado'?'encerrada':'aberta')}</td><td><div class="table-action"><button data-action="edit-product" data-id="${p.id}" aria-label="Editar ${e(p.nome)}">${icon('editar')}</button>${p.ativo?`<button data-action="delete-product" data-id="${p.id}" aria-label="Desativar ${e(p.nome)}">${icon('lixeira')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum produto encontrado.','Adicione um produto ou ajuste a busca.','')}
function ordersTable(ps){return ps.length?`<div class="table-scroll"><table><thead><tr><th>Pedido</th><th>Data</th><th>Itens</th><th>Total</th><th>Status</th><th>Ações</th></tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${e(p.codigo)}</strong></td><td>${date(p.criado_em)}</td><td>${p.itens.reduce((s,i)=>s+i.quantidade,0)}</td><td>${money(p.total)}</td><td>${badge(p.status)}</td><td><div class="row">${btn('Detalhes','order-detail',`data-id="${e(p.id)}"`,'light sm')}${['pago','preparando','enviado'].includes(p.status)?btn(p.status==='pago'?'Preparar':p.status==='preparando'?'Enviar':'Entregue','advance',`data-id="${e(p.id)}" data-value="${p.status==='pago'?'preparando':p.status==='preparando'?'enviado':'entregue'}"`,'sm'):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum pedido encontrado.','Os pedidos da loja aparecem aqui.','')}
function chart(ps){const ms=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);return {k:d.toISOString().slice(0,7),n:d.toLocaleDateString('pt-BR',{month:'short'}),v:0}});ps.forEach(p=>{const m=ms.find(m=>m.k===p.criado_em.slice(0,7));if(m)m.v++});const max=Math.max(1,...ms.map(m=>m.v));return `<div class="chart" role="img" aria-label="Pedidos por mês: ${ms.map(m=>m.n+' '+m.v).join(', ')}">${ms.map((m,i)=>`<div class="chart-col"><span>${m.v}</span><div class="chart-bar" style="height:${m.v/max*125}px;animation-delay:${i*60}ms"></div><span>${m.n}</span></div>`).join('')}</div>`}
async function panel(admin){if(!S.me)return needLogin();if(admin&&S.me.nivel!=='admin'||!admin&&!['vendedor','admin'].includes(S.me.nivel)){setTimeout(()=>go(homeFor(S.me)),0);return ''}const tab=location.hash.slice(1)||'visao',base=admin?'/admin.html':'/vendedor.html',nav=[['visao','Visão geral','grafico'],['produtos','Produtos','pacote'],['ofertas','Ofertas recebidas','tag'],['pedidos','Negociações aceitas','sacola'],...(admin?[['lojas','Lojas','loja'],['usuarios','Clientes e equipe','usuarios'],['solicitacoes','Solicitações','megafone'],['auditoria','Atividade','historico']]:[])];let h=nav.find(v=>v[0]===tab)?.[1]||'Visão geral',sub='Tudo o que sua loja precisa, em um só lugar.',action='',content='';
if(tab==='visao'){const [d,o]=await Promise.all([api('dashboard/'+(admin?'admin':'vendedor')),api('pedidos/'+(admin?'admin':'vendedor'))]);orders=o.pedidos;h=admin?'Um olhar para toda a Âmbar.':'Olá, '+e(S.me.nome.split(' ')[0])+'. Vamos brilhar?';sub=admin?'O movimento da sua comunidade, em um só lugar.':e(d.loja?.nome||'Sua loja')+' · Seus produtos, as ofertas dos compradores e as propostas que você aceita.';action=btn(icon('mais')+' Novo produto','new-product');const metrics=[[money(d.receita),admin?'Receita em pedidos':'Vendas da sua loja','cartao','Pedidos pagos e em andamento'],[d.ofertas,'Ofertas recebidas','tag','Propostas reais da demonstração'],[d.produtos,'Produtos ativos','pacote','Disponíveis na vitrine'],[admin?d.lojas:d.estoque_baixo,admin?'Lojas independentes':'Estoque baixo',admin?'loja':'alerta',admin?'Marcas da comunidade':'Produtos com até 5 unidades']];content=`<div class="metrics">${metrics.map(([v,l,i,s])=>`<div class="metric"><div class="metric-label">${l}${icon(i)}</div><strong>${v}</strong><small>${s}</small></div>`).join('')}</div><div class="dashboard-grid"><div class="panel-card"><div class="card-head"><h2>Pedidos ao longo do tempo</h2><span class="small muted">Últimos 6 meses</span></div>${chart(orders)}</div><div class="panel-card"><div class="card-head"><h2>Seu próximo passo</h2>${icon('brilho')}</div><div style="padding:24px"><h3 class="serif" style="font-size:25px;margin-bottom:12px">Novos achados, novas histórias.</h3><p class="small" style="margin-bottom:20px">Adicione um produto e veja ele aparecer na vitrine. Cadastre fotos e estoque, sem definir um preço. Depois acompanhe e aceite as ofertas recebidas.</p>${link('Gerenciar meus produtos '+icon('seta-direita'),base+'#produtos','btn light sm')}</div></div></div><div class="panel-card"><div class="card-head"><h2>Pedidos recentes</h2>${link('Ver todos',base+'#pedidos','text-link')}</div>${ordersTable(orders.slice(0,8))}</div>`;
}else if(tab==='produtos'){const d=await api('produtos/gerenciar?limite=100');products=d.itens;sub=d.total+' produtos cadastrados. Cuide dos detalhes que fazem a diferença.';action=btn(icon('mais')+' Novo produto','new-product');content=`<div class="panel-card"><div class="card-head"><div class="pills">${[['all','Todos'],['active','Ativos'],['low','Estoque baixo'],['inactive','Inativos']].map(([v,l],i)=>`<button class="pill ${i===0?'active':''}" data-action="stockfilter" data-value="${v}">${l}</button>`).join('')}</div><input id="product-search" aria-label="Buscar nos seus produtos" placeholder="Buscar produto..."></div><div id="product-table">${productsTable(products)}</div></div>`;
}else if(tab==='ofertas'){content=await receivedOffers();sub='Você decide qual proposta aceitar. Não há preço fixo nem encerramento automático.';}else if(tab==='pedidos'){orders=(await api('pedidos/'+(admin?'admin':'vendedor'))).pedidos;sub='Acompanhe cada etapa, do pagamento à entrega.';content=`<div class="panel-card"><div class="card-head"><h2>${orders.length} pedidos</h2><select id="status-filter" aria-label="Filtrar pedidos por status" style="max-width:210px"><option value="">Todos os status</option>${Object.entries(names).slice(0,6).map(([s,n])=>`<option value="${s}">${n}</option>`).join('')}</select></div><div id="orders-table">${ordersTable(orders)}</div></div>`;
}else if(tab==='lojas'){content=`<div class="shops">${(await api('lojas/gerenciar')).lojas.map(shop).join('')}</div>`;sub='As marcas que dão vida à nossa vitrine.';
}else if(tab==='usuarios'){const us=(await api('usuarios')).usuarios;sub='Contas de demonstração e suas permissões.';content=`<div class="panel-card"><div class="card-head"><h2>${us.length} usuários</h2></div><div class="table-scroll"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Status</th><th>Ações</th></tr></thead><tbody>${us.map(u=>`<tr><td>${e(u.nome)}</td><td>${e(u.email)}</td><td>${e(u.nivel)}</td><td>${badge(u.status)}</td><td>${u.id!==S.me.id?btn(u.status==='ativo'?'Bloquear':'Desbloquear','user-status',`data-id="${u.id}" data-value="${u.status==='ativo'?'bloqueado':'ativo'}"`,'light sm'):'Sua conta'}</td></tr>`).join('')}</tbody></table></div></div>`;
}else if(tab==='cupons'){const cs=(await api('cupons')).cupons;sub='Um incentivo a mais para o próximo encontro.';action=btn(icon('mais')+' Criar cupom','new-coupon');content=`<div class="panel-card"><div class="table-scroll"><table><thead><tr><th>Código</th><th>Benefício</th><th>Mínimo</th><th>Validade</th></tr></thead><tbody>${cs.map(c=>`<tr><td><strong>${e(c.codigo)}</strong><small>${e(c.descricao)}</small></td><td>${c.tipo==='percentual'?c.valor+'%':money(c.valor)}</td><td>${money(c.valor_minimo)}</td><td>${c.fim?date(c.fim):'Sem data definida'}</td></tr>`).join('')}</tbody></table></div></div>`;
}else if(tab==='solicitacoes'){const cs=(await api('solicitacoes')).itens;sub='Marcas que querem fazer parte da comunidade.';content=cs.length?cs.map(c=>`<div class="order-box"><div class="row between"><h3>${e(c.nome_loja)}</h3>${badge(c.status)}</div><p>${e(c.cidade)} · ${e(c.uf)}</p><p>${e(c.descricao)}</p><small class="muted">Recebida em ${date(c.criado_em)}. Aprovação disponível na versão MySQL.</small></div>`).join(''):empty('A próxima história ainda vai chegar.','Solicitações da página “Venda na Âmbar” aparecem aqui.','');
}else{const cs=(await api('auditoria')).itens;sub='Um registro das alterações nesta demonstração.';content=`<div class="panel-card">${cs.length?cs.map(c=>`<div class="activity"><strong>${e(c.acao)}</strong> · ${e(c.entidade)}<small>${e(c.usuario)} · ${new Date(c.criado_em).toLocaleString('pt-BR')}</small></div>`).join(''):empty('Tudo tranquilo por aqui.','As ações de gestão serão registradas neste espaço.','')}</div>`}
return `<div class="panel"><aside class="sidebar"><a class="brand" href="/index.html"><img src="/assets/marca/logo-ambar.svg" alt="Âmbar"></a><small>${admin?'ADMINISTRAÇÃO':'ESPAÇO DO VENDEDOR'}</small><nav class="sidebar-nav">${nav.map(([t,l,i])=>`<a class="${tab===t?'active':''}" href="${base}#${t}">${icon(i)} ${l}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="/index.html">${icon('loja')} Visitar a vitrine</a><a href="/login.html">${icon('usuario')} Trocar de perfil</a><a href="/index.html" data-action="logout">${icon('sair')} Sair</a></div></aside><div class="panel-main"><header class="panel-top"><span>${admin?'Administração Âmbar':'Painel da loja'} <span class="demo-chip" style="margin-left:10px">DEMONSTRAÇÃO</span></span><div class="row">${link('Ver a loja '+icon('seta-direita'),'/index.html','text-link')}<span class="avatar">${e(S.me.nome.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span></div></header><main class="panel-content page-in" id="conteudo"><div class="panel-title"><div><h1>${h}</h1><p>${sub}</p></div>${action}</div>${content}</main></div></div>`}
function modal(html){const d=$('#modal');d.innerHTML=html;d.showModal();requestAnimationFrame(()=>$('input,textarea,button',d)?.focus())}
const modalHead=h=>`<div class="dialog-head"><h2>${h}</h2><button class="icon-btn" type="button" data-action="close" aria-label="Fechar">${icon('fechar')}</button></div>`;
function confirm(h,p,action,attrs=''){modal(`${modalHead(h)}<p class="small">${p}</p><div class="form-actions">${btn('Voltar','close','','light')}${btn('Confirmar',action,attrs,'danger')}</div>`)}
function productForm(p={}){modal(`${modalHead(p.id?'Cada detalhe importa.':'Um novo achado vem aí.')}<p class="small" style="margin:-10px 0 22px">${p.id?'Atualize os detalhes do seu produto.':'Preencha os dados para colocar seu produto na vitrine.'}</p><form data-form="product" data-id="${p.id||''}">${field('Nome do produto','nome','text',p.nome||'','required minlength="3" maxlength="120"')}<div class="field"><label for="product-desc">Descrição</label><textarea id="product-desc" name="descricao" required minlength="10" maxlength="3000">${e(p.descricao||'')}</textarea></div><div class="fields">${field('Estoque','estoque','number',p.estoque??1,'required min="0" step="1"')}<div class="field"><label for="product-cat">Categoria</label><select id="product-cat" name="categoria_id">${S.cats.map(c=>`<option value="${c.id}" ${p.categoria?.id===c.id?'selected':''}>${e(c.nome)}</option>`).join('')}</select></div></div><div style="margin-top:18px">${field('URL da foto (https)','imagem','text',p.imagem||'','placeholder="Opcional: use uma URL pública de imagem"')}</div>${S.me.nivel==='admin'&&!p.id?`<div class="field"><label for="seller">Loja</label><select id="seller" name="vendedor_id">${S.shops.map(s=>`<option value="${s.usuario_id}">${e(s.nome)}</option>`).join('')}</select></div>`:''}<label class="checkline"><input type="checkbox" name="destaque" ${p.destaque?'checked':''}> Destaque na curadoria</label><div class="notice">Você cadastra o produto sem preço. Os compradores enviam ofertas por uma unidade e você escolhe qual aceitar.</div><label class="checkline"><input type="checkbox" name="ativo" ${p.ativo!==false?'checked':''}> Produto ativo na vitrine</label><p class="error" id="product-error" role="alert"></p><div class="form-actions"><button class="btn light" type="button" data-action="close">Cancelar</button><button class="btn">${icon('check')} ${p.id?'Salvar alterações':'Cadastrar produto'}</button></div></form>`)}
function enhance(){for(const im of $$('img'))im.addEventListener('error',()=>{if(!im.dataset.failed){im.dataset.failed='1';im.src='/assets/fotos/produto.svg'}},{once:true});observer?.disconnect();if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver'in window){observer=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add('reveal-visible');x.target.classList.remove('reveal-pending');observer.unobserve(x.target)}}),{threshold:.08});$$('.reveal').forEach(x=>{x.classList.add('reveal-pending');observer.observe(x)})}}
function anchor(){if(location.pathname.endsWith('index.html')&&location.hash)$('[id="'+location.hash.slice(1).replace(/[^a-z-]/g,'')+'"]')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
async function go(url,replace=false){history[replace?'replaceState':'pushState']({},'',url);await render();window.scrollTo(0,0);anchor()}
async function render(){const g=++renderId,path=location.pathname.split('/').pop()||'index.html',isPanel=['admin.html','vendedor.html'].includes(path),root=$('#app');root.innerHTML=isPanel?'<div class="loading"><span class="spinner"></span></div>':header()+'<main id="conteudo"><div class="loading"><span class="spinner" aria-label="Carregando"></span></div></main>'+footer();try{const routes={'index.html':home,'busca.html':()=>catalog(false),'loja.html':()=>catalog(true),'produto.html':detail,'login.html':()=>auth(false),'cadastro.html':()=>auth(true),'carrinho.html':()=>{setTimeout(()=>go('/conta.html#ofertas',true),0);return ''},'checkout.html':()=>{setTimeout(()=>go('/conta.html#ofertas',true),0);return ''},'pedido.html':order,'conta.html':account,'sobre.html':about,'vender.html':sell,'vendedor.html':()=>panel(false),'admin.html':()=>panel(true)};const html=routes[path]?await routes[path]():`<div class="wrap" style="padding-top:65px">${empty('404 · Achado não encontrado.','Este caminho ainda não tem uma história.','Voltar à vitrine','/index.html')}</div>`;if(g!==renderId)return;if(isPanel)root.innerHTML=html;else{$('#conteudo').innerHTML=html;$('#conteudo').classList.add('page-in')}if($('#sort'))$('#sort').value=new URLSearchParams(location.search).get('ordem')||'relevancia';document.title=path==='index.html'?'Âmbar · Achados que brilham':($('h1')?.textContent||'Sua loja')+' · Âmbar';enhance()}catch(err){if(g!==renderId)return;($('#conteudo')||root).innerHTML=`<div class="wrap" style="padding-top:40px">${empty(err.status===404?'Não encontramos esse achado.':'Não foi possível abrir esta página.',e(err.message),'Voltar para a vitrine','/index.html')}</div>`}}
async function refreshMe(){try{S.me=(await api('auth/me')).usuario;S.favs=new Set((await api('favoritos')).itens.map(p=>p.id))}catch{S.me=null;S.favs=new Set()}}
function safeReturn(){const p=new URLSearchParams(location.search).get('voltar');return p&&/^\/[a-z-]+\.html(?:[?#][^\s]*)?$/.test(p)?p:null}
async function add(id){let p=products.find(p=>p.id===id);if(!p)p=(await api('produtos/'+id)).produto;const i=S.cart.find(i=>i.produto_id===id),amount=location.pathname.endsWith('produto.html')&&detailProduct?.id===id?qty:1;if((i?.quantidade||0)+amount>p.estoque)throw new Error('Essa quantidade não está disponível.');if(i)i.quantidade+=amount;else S.cart.push({produto_id:id,quantidade:amount,nome:p.nome,imagem:p.imagem});persist();const b=$('.bag');b?.classList.remove('pulse');if(b){void b.offsetWidth;b.classList.add('pulse')}toast('Achado adicionado à sua sacola.')}
function checkoutData(f){const v=Object.fromEntries(new FormData(f));return {itens:S.cart,chave:orderKey,cupom:v.cupom||'',forma_pagamento:v.forma_pagamento,parcelas:Number(v.parcelas||1),endereco:Object.fromEntries(['destinatario','cep','logradouro','numero','bairro','complemento','cidade','uf'].map(k=>[k,v[k]]))}}
let quoteSeq=0;
async function updateQuote(){const f=$('#checkout');if(!f)return;const n=++quoteSeq,d=await api('pedidos/simular','POST',checkoutData(f));if(n!==quoteSeq)return;quote=d;$('#quote').innerHTML=quoteHTML(d);return d}
function filterProducts(){const q=($('#product-search')?.value||'').toLowerCase(),f=$('[data-action="stockfilter"].active')?.dataset.value||'all';$('#product-table').innerHTML=productsTable(products.filter(p=>p.nome.toLowerCase().includes(q)&&(f==='all'||f==='active'&&p.ativo||f==='low'&&p.ativo&&p.estoque<=5||f==='inactive'&&!p.ativo)));enhance()}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(b){ev.preventDefault();if(b.disabled)return;const a=b.dataset.action,id=Number(b.dataset.id),v=b.dataset.value;try{
if(a==='reload'){await render();return}
if(a==='refresh-offers'){await refreshBids();toast('Ofertas atualizadas.');return}
if(a==='accept-offer'){confirm('Aceitar esta oferta?',`A proposta de <strong>${money(Number(v))}</strong> será aceita. Uma unidade será reservada para o comprador e a rodada será encerrada. Nenhum valor é movimentado nesta demonstração.`,'confirm-offer',`data-id="${e(b.dataset.id)}"`);return}
if(a==='confirm-offer'){b.disabled=true;await api('lances/'+b.dataset.id+'/aceitar','POST',{});$('#modal').close();toast('Oferta aceita. O comprador já pode acompanhar a negociação.');await render();return}
if(a==='reopen-offers'){confirm('Abrir uma nova rodada?','A rodada anterior precisa estar concluída ou cancelada. As ofertas antigas ficam no histórico.','confirm-reopen',`data-id="${id}"`);return}
if(a==='confirm-reopen'){b.disabled=true;await api('produtos/'+id+'/reabrir','POST',{});$('#modal').close();toast('Nova rodada de ofertas aberta.');await render();return}
if(a==='close'){$('#modal').close();return}
if(a==='add'){await add(id);return}
if(a==='sound'){S.sound=!S.sound;try{localStorage.setItem('ambar:sound:v3',S.sound?'1':'0')}catch{}b.innerHTML=icon(S.sound?'som':'som-mudo');b.setAttribute('aria-label',S.sound?'Desativar sons':'Ativar sons');toast(S.sound?'Sons ativados.':'Sons desativados.');return}
if(a==='favorite'){if(!S.me){toast('Entre para guardar seus favoritos.');go('/login.html?voltar='+encodeURIComponent(location.pathname+location.search));return}const active=S.favs.has(id);b.disabled=true;await api('favoritos',active?'DELETE':'POST',{produto_id:id});active?S.favs.delete(id):S.favs.add(id);$$(`[data-action="favorite"][data-id="${id}"]`).forEach(x=>{x.classList.toggle('active',!active);x.setAttribute('aria-pressed',String(!active))});b.disabled=false;toast(active?'Achado removido dos favoritos.':'Achado guardado com carinho.');if(location.hash==='#favoritos')await render();return}
if(a==='homefilter'){$$('[data-action="homefilter"]').forEach(x=>x.classList.toggle('active',x===b));const ps=v==='oferta'?products.filter(p=>p.total_ofertas>0):v==='novo'?[...products].sort((a,b)=>b.id-a.id):selected(products);$('#home-products').innerHTML=ps.slice(0,8).map(card).join('');enhance();return}
if(a==='filters'){$('.filters').classList.toggle('open');return}
if(a==='page'){const q=new URLSearchParams(location.search);q.set('pagina',v);await go(location.pathname+'?'+q);return}
if(a==='qty'){qty=Math.max(1,Math.min(detailProduct.estoque,qty+Number(v)));$('#qty').textContent=qty;return}
if(a==='tab'){const p=detailProduct;$$('[data-action="tab"]').forEach(x=>x.classList.toggle('active',x===b));$('#product-tab').innerHTML=v==='descricao'?desc(p):v==='reviews'?(p.reviews.length?p.reviews.map(r=>`<div class="review"><div class="rating">${icon('estrela')} ${r.nota}/5 · Compra verificada</div><h3>${e(r.titulo)}</h3><p>${e(r.comentario)}</p></div>`).join(''):'<p class="small">Este achado ainda não recebeu avaliações.</p>'):`${p.questions.map(r=>`<div class="review"><h3>${e(r.pergunta)}</h3><p>${e(r.resposta||'Aguardando resposta da loja.')}</p></div>`).join('')}<form data-form="question" style="margin-top:20px"><label for="question">Ficou com alguma dúvida?</label><textarea id="question" name="pergunta" minlength="10" required></textarea><button class="btn sm" style="margin-top:10px">Enviar pergunta</button></form>`;return}
if(a==='demo-login'){b.disabled=true;const ret=safeReturn();await api('auth/login','POST',{email:v+'@ambar.test',senha:'Ambar@2026'});await refreshMe();toast('Bem-vindo à Âmbar.');await go(ret||homeFor(S.me));return}
if(a==='logout'||a==='logout-all'){await api(a==='logout'?'auth/logout':'auth/logout-todos','POST',{});S.me=null;S.favs=new Set();$('#modal').close();toast('Até o próximo achado.');await go('/index.html');return}
if(a==='cartqty'){const i=S.cart.find(i=>i.produto_id===id),p=products.find(p=>p.id===id),next=i.quantidade+Number(v);if(next<1)return;if(!p||next>p.estoque)throw new Error('Quantidade indisponível em estoque.');i.quantidade=next;persist();await render();return}
if(a==='remove'){S.cart=S.cart.filter(i=>i.produto_id!==id);persist();toast('Produto removido da sacola.');await render();return}
if(a==='example-address'){fillAddress({destinatario:S.me.nome,cep:'96810000',logradouro:'Rua das Flores',numero:'123',bairro:'Centro',cidade:'Santa Cruz do Sul',uf:'RS',complemento:'Endereço fictício'});return}
if(a==='payment'){const prev=$('[name="forma_pagamento"]').value;$('[name="forma_pagamento"]').value=v;try{await updateQuote();$$('[data-action="payment"]').forEach(x=>x.classList.toggle('active',x===b));$('#installments').hidden=v!=='cartao'}catch(err){$('[name="forma_pagamento"]').value=prev;throw err}return}
if(a==='coupon'){b.disabled=true;await updateQuote();toast(quote.cupom?'Cupom aplicado: '+money(quote.desconto_cupom)+' de desconto.':'Resumo atualizado.');b.disabled=false;return}
if(a==='pay'){b.disabled=true;await api('pedidos/'+b.dataset.id+'/pagar','POST',{});toast('Pagamento de teste aprovado.');await render();return}
if(a==='cancel'){confirm('Cancelar este pedido?','O estoque será devolvido à loja. Nenhuma cobrança real foi feita.','confirm-cancel',`data-id="${e(b.dataset.id)}"`);return}
if(a==='confirm-cancel'){b.disabled=true;await api('pedidos/'+b.dataset.id+'/cancelar','POST',{});$('#modal').close();toast('Pedido cancelado.');await render();return}
if(a==='new-address'){modal(`${modalHead('Um endereço para seus achados.')}<form data-form="address">${addressFields()}<div class="form-actions"><button class="btn">Salvar endereço</button></div></form>`);return}
if(a==='delete-address'){confirm('Remover este endereço?','Você pode cadastrar outro endereço a qualquer momento.','confirm-address',`data-id="${e(b.dataset.id)}"`);return}
if(a==='confirm-address'){await api('enderecos/'+b.dataset.id,'DELETE');$('#modal').close();toast('Endereço removido.');await render();return}
if(a==='new-product'){productForm();return}
if(a==='edit-product'){productForm((await api('produtos/'+id)).produto);return}
if(a==='delete-product'){const p=products.find(p=>p.id===id);confirm('Retirar este achado da vitrine?',e(p.nome)+' ficará inativo. Os pedidos antigos serão preservados. Você pode reativá-lo na edição.','confirm-product',`data-id="${id}"`);return}
if(a==='confirm-product'){b.disabled=true;await api('produtos/'+id,'DELETE');$('#modal').close();toast('Produto retirado da vitrine.');await render();return}
if(a==='stockfilter'){$$('[data-action="stockfilter"]').forEach(x=>x.classList.toggle('active',x===b));filterProducts();return}
if(a==='order-detail'){const p=orders.find(p=>String(p.id)===b.dataset.id);modal(`${modalHead(e(p.codigo))}${badge(p.status)}<p class="small" style="margin:12px 0">${date(p.criado_em)} · ${money(p.total)}</p>${orderItems(p)}<p class="small" style="margin-top:20px">Pedido de demonstração. Não há entrega física.</p>`);enhance();return}
if(a==='advance'){b.disabled=true;await api('pedidos/'+b.dataset.id+'/status','POST',{status:v});toast('Etapa do pedido atualizada.');await render();return}
if(a==='user-status'){confirm(v==='ativo'?'Desbloquear esta conta?':'Bloquear esta conta?',v==='ativo'?'A conta poderá entrar novamente.':'A conta perderá acesso enquanto estiver bloqueada.','confirm-user',`data-id="${id}" data-value="${v}"`);return}
if(a==='confirm-user'){await api('usuarios/'+id,'PUT',{status:v});$('#modal').close();toast('Conta atualizada.');await render();return}
if(a==='new-coupon'){modal(`${modalHead('Um incentivo para descobrir.')}<form data-form="coupon">${field('Código','codigo','text','','required minlength="3" maxlength="25"')}${field('Descrição','descricao','text','','required')}<div class="fields">${field('Desconto (%)','valor','number','10','required min="1" max="50"')}${field('Compra mínima (R$)','valor_minimo','number','0','required min="0" step="0.01"')}</div><div class="form-actions"><button class="btn">Criar cupom</button></div></form>`);return}
}catch(err){b.disabled=false;toast(err.message,true)}return}
const a=ev.target.closest('a[href]');if(a&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&!a.target&&!a.hasAttribute('download')){const u=new URL(a.href);if(u.origin===location.origin&&(u.pathname.endsWith('.html')||u.pathname==='/')){ev.preventDefault();go(u.pathname+u.search+u.hash)}}});
function fillAddress(a){for(const [k,v] of Object.entries(a)){const f=$(`#checkout [name="${k}"]`);if(f)f.value=v||''}}
document.addEventListener('submit',async ev=>{const f=ev.target.closest('[data-form]');if(!f)return;ev.preventDefault();const type=f.dataset.form,v=Object.fromEntries(new FormData(f)),submit=$('button[type="submit"],button:not([type])',f);if(submit?.disabled)return;if(submit)submit.disabled=true;try{
if(type==='offer'){const key=f.dataset.key||(f.dataset.key=uid());await api('produtos/'+detailProduct.id+'/lances','POST',{valor:v.valor,chave:key});delete f.dataset.key;f.reset();await refreshBids();toast('Sua oferta foi enviada à loja.');return}
if(type==='search'){await go('/busca.html?'+new URLSearchParams({q:v.q.trim()}));return}
if(type==='price'){if(v.min&&v.max&&Number(v.min)>Number(v.max))throw new Error('O mínimo deve ser menor que o máximo.');const q=new URLSearchParams(location.search);q.delete('pagina');for(const k of ['min','max'])v[k]?q.set(k,v[k]):q.delete(k);await go(location.pathname+'?'+q);return}
if(type==='newsletter'){toast((await api('newsletter','POST',v)).mensagem);f.reset();return}
if(type==='login'||type==='register'){const ret=safeReturn();await api(type==='login'?'auth/login':'auth/cadastro','POST',v);await refreshMe();toast('Que bom ter você aqui.');await go(ret||homeFor(S.me));return}
if(type==='shipping'){const d=await api('frete/calcular','POST',{cep:v.cep,subtotal:detailProduct.preco*qty,produto_id:detailProduct.id});$('#shipping-result').textContent=`Entrega econômica: ${d.opcoes[0].valor?money(d.opcoes[0].valor):'grátis'} · até 7 dias úteis (estimativa de demonstração).`;return}
if(type==='question'){await api('produtos/'+detailProduct.id+'/perguntas','POST',v);toast('Pergunta enviada à loja.');await render();return}
if(type==='checkout'){const d=await api('pedidos','POST',checkoutData(f));S.cart=[];persist();toast('Pedido de teste criado.');await go('/pedido.html?id='+d.pedido.id);return}
if(type==='profile'){S.me={...S.me,...(await api('auth/perfil','PUT',v)).usuario};toast('Seu nome foi atualizado.');await render();return}
if(type==='password'){await api('auth/senha','PUT',v);S.me=null;toast('Senha alterada. Entre novamente.');await go('/login.html');return}
if(type==='address'){await api('enderecos','POST',v);$('#modal').close();toast('Endereço salvo.');await render();return}
if(type==='sell'){await api('solicitacoes','POST',v);toast('Sua marca foi apresentada ao administrador.');f.reset();return}
if(type==='product'){await api('produtos'+(f.dataset.id?'/'+f.dataset.id:''),f.dataset.id?'PUT':'POST',{...v,destaque:!!v.destaque,frete_gratis:!!v.frete_gratis,ativo:!!v.ativo});$('#modal').close();toast(f.dataset.id?'Produto atualizado.':'Seu novo achado já está cadastrado.');if(location.hash!=='#produtos')await go(location.pathname+'#produtos');else await render();return}
if(type==='coupon'){await api('cupons','POST',v);$('#modal').close();toast('Cupom criado.');await render();return}
}catch(err){const target=type==='offer'?$('#offer-error'):type==='product'?$('#product-error'):['login','register'].includes(type)?$('#auth-error'):type==='checkout'?$('#checkout-error'):null;if(target)target.textContent=err.message;else toast(err.message,true)}finally{if(submit)submit.disabled=false}});
document.addEventListener('input',ev=>{if(ev.target.id==='product-search')filterProducts();if(ev.target.name==='valor'&&ev.target.closest('[data-form="offer"]'))delete ev.target.closest('form').dataset.key});
document.addEventListener('change',ev=>{if(ev.target.id==='sort'){const q=new URLSearchParams(location.search);q.set('ordem',ev.target.value);q.delete('pagina');go(location.pathname+'?'+q)}if(ev.target.id==='addresses'&&ev.target.value!==''){const a=JSON.parse($('#saved-addresses').textContent)[Number(ev.target.value)];if(a)fillAddress(a)}if(ev.target.id==='status-filter')$('#orders-table').innerHTML=ordersTable(orders.filter(p=>!ev.target.value||p.status===ev.target.value))});
window.addEventListener('popstate',()=>render().then(anchor));window.addEventListener('storage',ev=>{if(ev.key==='ambar:cart:v3'){try{S.cart=JSON.parse(ev.newValue||'[]');$$('[data-count]').forEach(x=>x.textContent=count())}catch{}}});
$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close()}});
(async()=>{try{const [c,s]=await Promise.all([api('categorias'),api('lojas'),refreshMe()]);S.cats=c.categorias;S.shops=s.lojas;await render();anchor()}catch(err){$('#app').innerHTML=header()+`<main class="wrap" style="padding-top:40px">${empty('A vitrine está se preparando.',e(err.message),'Tentar novamente','/index.html')}</main>`+footer()}})();
async function myOffers(){if(S.me.nivel!=='comprador')return `<div class="notice">${icon('info')} Use o perfil comprador para enviar ofertas. As propostas recebidas ficam no painel da loja.</div>${link('Abrir meu painel',homeFor(S.me),'btn light')}`;const bids=(await api('lances/meus')).itens;return `<div class="row between" style="margin-bottom:20px"><p class="small">Acompanhe seus lances e as decisões da loja.</p>${btn('Atualizar','reload','','light sm')}</div>${bids.length?bids.map(b=>`<article class="offer-card"><img src="${e(b.produto.imagem)}" alt="${e(b.produto.nome)}"><div><a class="shop-label" href="/loja.html?slug=${b.produto.loja.slug}">${e(b.produto.loja.nome)}</a><h3><a href="/produto.html?id=${b.produto_id}">${e(b.produto.nome)}</a></h3><p class="small">Sua oferta: <strong>${money(b.valor)}</strong> · ${new Date(b.criado_em).toLocaleString('pt-BR')}</p><p class="small muted">Maior oferta atual: ${money(b.produto.maior_oferta)}</p></div><div class="offer-card-action">${badge(b.status)}${b.pedido_id?link('Ver negociação '+icon('seta-direita'),'/pedido.html?id='+b.pedido_id,'btn sm'):link('Ver achado','/produto.html?id='+b.produto_id,'btn light sm')}</div></article>`).join(''):empty('Seu próximo achado começa com uma oferta.','Escolha um produto e ofereça o valor que faz sentido para você.','Encontrar um achado')}`}
async function receivedOffers(){const bids=(await api('lances/vendedor')).itens;if(!bids.length)return empty('Os próximos lances chegam por aqui.','Cadastre seus produtos sem preço e receba as ofertas dos compradores.','');return `<div class="notice">${icon('info')} Aceitar uma oferta reserva 1 unidade e cria uma negociação para o comprador. A escolha é sua; a maior oferta fica destacada como referência.</div><div class="panel-card"><div class="table-scroll"><table><thead><tr><th>Produto</th><th>Participante</th><th>Oferta</th><th>Status</th><th>Ação</th></tr></thead><tbody>${bids.map(b=>`<tr><td><div class="product-cell"><img src="${e(b.produto.imagem)}" alt=""><a href="/produto.html?id=${b.produto_id}">${e(b.produto.nome)}</a></div></td><td>${e(b.participante)}<small>${date(b.criado_em)}</small></td><td><strong>${money(b.valor)}</strong>${b.valor===b.produto.maior_oferta?'<small>MAIOR OFERTA</small>':''}</td><td>${badge(b.status)}</td><td>${b.status==='aberta'&&b.produto.negociacao_status==='aberto'?btn('Aceitar oferta','accept-offer',`data-id="${e(b.id)}" data-value="${b.valor}"`,'sm'):b.status==='aceita'?btn('Nova rodada','reopen-offers',`data-id="${b.produto_id}"`,'light sm'):''}</td></tr>`).join('')}</tbody></table></div></div>`}
setInterval(()=>{if(document.visibilityState==='visible'&&location.pathname.endsWith('produto.html')&&!$('#modal').open)refreshBids().catch(()=>{})},10000);
